window.docContents[157].resolve({"/Basics/#Logical-Foundations--Basics___-Functional-Programming-in-Lean--Proof-by-Rewriting--Working-with-Numerals":{"contents":"We know from our definitions above that one is just succ zero,\ntwo is succ one, and so on. We can write rules for these equalities too:\n\ntheorem one_eq_succ_zero : one = succ zero := by rfl\ntheorem two_eq_succ_one : two = succ one := by rfl\ntheorem three_eq_succ_two : three = succ two := by rfl\ntheorem four_eq_succ_three : four = succ three := by rfl\n\n\n\n\n\n\n\n\n","context":"Logical Foundations\u0009Basics: Functional Programming in Lean\u0009Proof by Rewriting","header":"2.2.7. Working with Numerals","id":"/Basics/#Logical-Foundations--Basics___-Functional-Programming-in-Lean--Proof-by-Rewriting--Working-with-Numerals"},"/Lists/#Logical-Foundations--Lists___-Working-with-Structured-Data--Lists-of-Numbers--Counting":{"contents":"Define a count function for NatLists that counts the number of times an element n appears in the list.def count (n : Nat) (l : NatList) : Nat := sorry\nNow, prove these lemmas which should hold about your definition.theorem count_nil (n : Nat) : count n [] = 0 := sorry\n\ntheorem count_cons_def (n h : Nat) (t : NatList) :\n    count n (h :: t) = bif n == h then (count n t) + 1 else count n t := sorry\n\ntheorem count_cons_same (n₁ n₂ : Nat) (t : NatList) (h : (n₁ == n₂) = true) :\n    count n₁ (n₂ :: t) = count n₁ t + 1 := by\n  sorry\n\ntheorem count_cons_diff (n₁ n₂ : Nat) (t : NatList) (h : (n₁ == n₂) = false) :\n    count n₁ (n₂ :: t) = count n₁ t := by\n  sorry\n\nexample : count 1 [1] = 1 := by\n  rw [count_cons_same _ _ _ rfl]\n  rw [count_nil]\n\nexample : count 2 [2, 2] = 2 := sorry\n\ntheorem test_count1 : count 1 [1, 1, 4] = 2 := sorry\n\ntheorem test_count2 : count 5 [1, 1, 4] = 0 := sorry\n\n\nAgain, all these proofs could be completed with just rfl, because the proof is computationally straight-forward -- compute both sides of the equality and check if they are the same.\n\nexample : count 1 [1, 2, 3, 1, 4, 1] = 3 := sorry\nexample : count 6 [1, 2, 3, 1, 4, 1] = 0 := sorry\n\n\n","context":"Logical Foundations\u0009Lists: Working with Structured Data\u0009Lists of Numbers","header":"5.3.4. Counting","id":"/Lists/#Logical-Foundations--Lists___-Working-with-Structured-Data--Lists-of-Numbers--Counting"},"/Lists/#Logical-Foundations--Lists___-Working-with-Structured-Data--Lists-of-Numbers--Removing":{"contents":"Here are some more NatList functions for you to practice with.When removeOne is applied to a list without the number to\nremove, it should return the same list unchanged.def removeOne (n : Nat) (l : NatList) : NatList := sorry\n\ntheorem removeOne_nil (n : Nat) : removeOne n nil = nil := sorry\n\ntheorem removeOne_cons_same (n₁ n₂ : Nat) (t : NatList) (h : (n₁ == n₂) = true) :\n    removeOne n₁ (n₂ :: t) = t := by\n  sorry\n\ntheorem removeOne_cons_diff (n₁ n₂ : Nat) (t : NatList) (h : (n₁ == n₂) = false) :\n    removeOne n₁ (n₂ :: t) = n₂ :: removeOne n₁ t := by\n  sorry\nexample : removeOne 5 [1, 5, 4] = [1, 4] := by\n  rw [removeOne_cons_diff _ _ _ rfl]\n  rw [removeOne_cons_same _ _ _ rfl]\n\nexample : count 5 (removeOne 5 [1, 5, 4]) = 0 := sorry\n\ntheorem test_removeOne1 : count 4 (removeOne 5 [4, 5, 1, 4]) = 2 := sorry\ntheorem test_removeOne2 : count 5 (removeOne 5 [1, 5, 5, 4]) = 1 := sorry\ndef removeAll (n : Nat) (l : NatList) : NatList := sorry\n\ntheorem removeAll_nil (n : Nat) : removeAll n [] = [] := sorry\n\ntheorem removeAll_cons_same (n₁ n₂ : Nat) (t : NatList) (h : (n₁ == n₂) = true) :\n    removeAll n₁ (n₂ :: t) = removeAll n₁ t := by\n  sorry\n\ntheorem removeAll_cons_diff (n₁ n₂ : Nat) (t : NatList) (h : (n₁ == n₂) = false) :\n    removeAll n₁ (n₂ :: t) = n₂ :: removeAll n₁ t := by\n  sorry\nexample : count 5 (removeAll 5 [5, 1]) = 0 := by\n  rw [removeAll_cons_same _ _ _ rfl]\n  rw [removeAll_cons_diff _ _ _ rfl]\n  rw [removeAll_nil]\n  rw [count_cons_diff _ _ _ rfl]\n  rw [count_nil]\n\nexample : count 5 (removeAll 5 [5, 5]) = 0 := sorry\n\ntheorem test_removeAll₁ : count 4 (removeAll 5 [4, 5, 4]) = 2 := sorry\ntheorem test_removeAll2 : count 5 (removeAll 5 [2, 5, 5, 5, 1]) = 0 := sorry\n\n\n","context":"Logical Foundations\u0009Lists: Working with Structured Data\u0009Lists of Numbers","header":"5.3.6. Removing","id":"/Lists/#Logical-Foundations--Lists___-Working-with-Structured-Data--Lists-of-Numbers--Removing"},"/Logic/#Logical-Foundations--Logic-in-Lean--Logical-Connectives":{"contents":"\n\n\n\n\n\n","context":"Logical Foundations\u0009Logic in Lean","header":"8.2. Logical Connectives","id":"/Logic/#Logical-Foundations--Logic-in-Lean--Logical-Connectives"}});